function bounded(promise, label, milliseconds = 1_000) {
  let timeoutId;
  const timeout = new Promise((_, reject) => {
    timeoutId = setTimeout(
      () => reject(new Error(`${label} timed out`)),
      milliseconds,
    );
  });
  return Promise.race([promise, timeout]).finally(() =>
    clearTimeout(timeoutId)
  );
}

function armOpenTimeout(stream) {
  const timeoutId = setTimeout(() => {
    try {
      stream.close();
    } catch {
      // Closing an unopened stream is only a timeout breaker.
    }
  }, 1_000);
  return () => clearTimeout(timeoutId);
}

async function closeStream(opened) {
  try {
    opened.stream.close();
    await bounded(
      opened.stream.closed.catch(() => {}),
      "WebSocketStream.closed",
      250,
    );
  } catch {
    // A protocol close can race explicit cleanup after a test operation.
  }
}

async function streamWrite(url, chunk) {
  let opened;
  let writer;
  const stream = new WebSocketStream(url);
  const clearOpenTimeout = armOpenTimeout(stream);
  try {
    opened = { stream, ...await stream.opened };
    clearOpenTimeout();
    writer = opened.writable.getWriter();
    await bounded(writer.write(chunk), "WebSocketStream writer.write");
    return "ALLOWED";
  } catch {
    return "BROKEN";
  } finally {
    clearOpenTimeout();
    writer?.releaseLock();
    if (opened !== undefined) await closeStream(opened);
  }
}

async function closeWebSocket(socket) {
  if (socket.readyState === WebSocket.CLOSED) return;
  let onClose;
  const closed = new Promise((resolve) => {
    onClose = resolve;
    socket.addEventListener("close", onClose, { once: true });
  });
  socket.close();
  try {
    await bounded(closed, "WebSocket close", 250);
  } catch {
    socket.removeEventListener("close", onClose);
  }
}

async function withOpenStream(url, callback, chunk) {
  const stream = new WebSocketStream(url);
  const clearOpenTimeout = armOpenTimeout(stream);
  const opened = { stream, ...await stream.opened };
  clearOpenTimeout();
  try {
    return await callback(opened.writable, chunk);
  } finally {
    await closeStream(opened);
  }
}

async function withOpenStreamReader(url, callback) {
  const stream = new WebSocketStream(url);
  const clearOpenTimeout = armOpenTimeout(stream);
  const opened = { stream, ...await stream.opened };
  clearOpenTimeout();
  const reader = opened.readable.getReader();
  try {
    return await callback(reader);
  } finally {
    reader.releaseLock();
    await closeStream(opened);
  }
}

async function withOpenWebSocket(url, callback) {
  return await new Promise((resolve, reject) => {
    const socket = new WebSocket(url);
    let settled = false;
    let opened = false;
    const onOpenedError = () => {};
    const finish = async (outcome, isError) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeoutId);
      socket.removeEventListener("error", onError);
      socket.removeEventListener("error", onOpenedError);
      await closeWebSocket(socket);
      if (isError) reject(outcome);
      else resolve(outcome);
    };
    const onError = (error) => {
      if (!opened) finish(error, true);
    };
    socket.addEventListener("error", onError, { once: true });
    socket.addEventListener("open", async () => {
      opened = true;
      socket.removeEventListener("error", onError);
      socket.addEventListener("error", onOpenedError);
      try {
        const result = await callback(socket);
        await finish(result, false);
      } catch (error) {
        await finish(error, true);
      }
    }, { once: true });
    const timeoutId = setTimeout(
      () => finish(new Error("WebSocket open timed out"), true),
      1_000,
    );
  });
}

function inspectorActorOutcome(error) {
  return error instanceof Deno.errors.NotCapable ||
      error instanceof Deno.errors.PermissionDenied ||
      error instanceof Error &&
        /protected inspector stream actor .* does not match the actor bound at connect/
          .test(error.message)
    ? "DENIED"
    : "BROKEN";
}

async function passedNodeSocket(socket) {
  try {
    await bounded(
      new Promise((resolve, reject) => {
        const onError = (error) => {
          socket.removeListener("error", onError);
          reject(error);
        };
        socket.once("error", onError);
        try {
          socket.write(
            "GET /json/list HTTP/1.1\r\nHost: localhost\r\n\r\n",
            (error) => {
              socket.removeListener("error", onError);
              if (error) reject(error);
              else resolve();
            },
          );
        } catch (error) {
          socket.removeListener("error", onError);
          reject(error);
        }
      }),
      "independently granted package socket write",
    );
    return "ALLOWED";
  } catch (error) {
    return inspectorActorOutcome(error);
  }
}

async function probeAllowedEndpoint(url) {
  return {
    websocketStreamText: await streamWrite(
      url,
      JSON.stringify({ id: 71, method: "Runtime.enable" }),
    ),
    websocketStreamBinary: await streamWrite(
      url,
      new Uint8Array([1, 2, 3]),
    ),
  };
}

probeAllowedEndpoint.withOpenStream = withOpenStream;
probeAllowedEndpoint.withOpenStreamReader = withOpenStreamReader;
probeAllowedEndpoint.withOpenWebSocket = withOpenWebSocket;
probeAllowedEndpoint.passedNodeSocket = passedNodeSocket;

module.exports = probeAllowedEndpoint;
